import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Nettoyeurs haute pression","description":"","frontmatter":{},"headers":[],"relativePath":"fr/car-wash/pressure-washers.md","filePath":"fr/car-wash/pressure-washers.md"}'),r={name:"fr/car-wash/pressure-washers.md"};function n(u,e,i,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="nettoyeurs-haute-pression" tabindex="-1">Nettoyeurs haute pression <a class="header-anchor" href="#nettoyeurs-haute-pression" aria-label="Permalink to &quot;Nettoyeurs haute pression&quot;">​</a></h1><p>Les nettoyeurs haute pression sont l&#39;option en libre-service : le joueur se gare, va au nettoyeur et nettoie le véhicule niveau par niveau. Chaque niveau de saleté enlevé est payé.</p><h2 id="ou-ils-se-trouvent" tabindex="-1">Où ils se trouvent <a class="header-anchor" href="#ou-ils-se-trouvent" aria-label="Permalink to &quot;Où ils se trouvent&quot;">​</a></h2><p>Deux façons, utilisables ensemble :</p><ul><li><strong>Props du monde</strong> : chaque prop listé dans <code>ManualModels</code> devient un nettoyeur, partout où la carte en a un. Par défaut c&#39;est <code>prop_gas_airunit01</code>, la borne de gonflage des stations-service.</li><li><strong>Stations placées</strong> : ajoutez une entrée à <code>ManualStations</code> dans <code>/nay</code>, placez-vous à l&#39;endroit voulu et appuyez sur <strong>Utiliser ma position</strong>.</li></ul><p>Avec <code>ShowBlips</code> activé, les stations placées apparaissent sur la carte.</p><h2 id="utilisation-par-les-joueurs" tabindex="-1">Utilisation par les joueurs <a class="header-anchor" href="#utilisation-par-les-joueurs" aria-label="Permalink to &quot;Utilisation par les joueurs&quot;">​</a></h2><ul><li>Avec <code>InteractionMode</code> sur <code>key</code>, les joueurs vont au nettoyeur et appuient sur <strong>E</strong>.</li><li>Avec <code>target</code>, ils utilisent l&#39;œil de target (ox_target ou qb-target).</li></ul><p>Le niveau de saleté du véhicule et le prix par niveau sont affichés. Le nettoyage enlève un niveau toutes les <code>ManualSecondsPerLevel</code> secondes, et chaque niveau coûte <code>ManualPricePerLevel</code> (remises par métier comprises), prélevé sur le compte réglé dans <code>Account</code>. Les joueurs peuvent s&#39;arrêter à tout moment et ne paient que ce qu&#39;ils ont nettoyé.</p><p>Désactivez tous les nettoyeurs avec <code>ManualEnabled</code>. Tous les réglages sont sur la page <a href="/fr/car-wash/settings#nettoyeurs-haute-pression">Réglages</a>.</p>',10)])])}const v=t(r,[["render",n]]);export{h as __pageData,v as default};
